/* 声明层顺序：越靠后优先级越高 */
@layer reset, base, components, utilities;

/* reset 层：优先级最低 */
@layer reset {
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }
}

/* base 层：基础样式 */
@layer base {
  body {
    font-family: system-ui, sans-serif;
    line-height: 1.6;
    color: #333;
  }
  a {
    color: #e8590c;
    text-decoration: none;
  }
  a:hover {
    text-decoration: underline;
  }
}

/* components 层：组件样式 */
@layer components {
  .btn {
    padding: 8px 16px;
    border-radius: 6px;
    border: none;
    cursor: pointer;
    font-size: 14px;
  }
  .btn-primary {
    background: #e8590c;
    color: #fff;
  }
  .btn-secondary {
    background: #f1f3f5;
    color: #333;
  }
}

/* utilities 层：工具类（优先级最高的层） */
@layer utilities {
  .text-center {
    text-align: center;
  }
  .font-bold {
    font-weight: 700;
  }
  .m-0 {
    margin: 0;
  }
  .p-0 {
    padding: 0;
  }
}

/* 未分层的样式：优先级高于所有 @layer */
.override {
  color: #000;
  /* 即使在 utilities 层之后声明，也比 utilities 层优先级低？不！
     未分层的样式优先级最高 */
}

/* 嵌套层 */
@layer components {
  @layer button {
    .btn {
      /* 内部嵌套层 */
    }
  }
}

